  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "Molecule 1 had an average absolute oral bioavailability of 4% (range 1-9%) in humans, well below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Molecule 8 had an estimated absolute oral bioavailability of 6-18% in humans, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Molecule 5 had an absolute oral bioavailability of 40-50% at a 200 mg oral dose in HIV-infected men, which is above the 20% threshold and contradicts a low prediction.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most transferred human evidence, including absolute measurements, shows oral bioavailability below 20% (4%, 4.1%, 7%, 10%, 6-18%, ~10%), while only didanosine shows adult values above 20% with conflicting pediatric values; therefore low is better supported.",
  "evidence_gaps": [
    "Molecule 5 has conflicting adult (40-50%) and pediatric (19%) absolute bioavailability data, creating uncertainty about the threshold classification.",
    "Several records are qualitative ('poor'/'low') or based on non-absolute methods; these were discounted in favor of numeric human measurements."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

